async function load(url) {
  try {
    const res = await fetch(url);
    return res.ok ? "ok" : "http " + res.status;
  } catch (e) {
    // Chrome: TypeError "Failed to fetch"; Firefox: "NetworkError when attempting..."; Safari: "Load failed"
    return e instanceof TypeError ? "network failure" : "other: " + e.name;
  }
}
