const hints = [
  [/Cannot read properties of (undefined|null) \(reading '(.+)'\)/, (m) => "The value before ." + m[2] + " is " + m[1] + ". Check it or use ?."],
  [/(.+) is not a function/, (m) => m[1] + " is not callable: check spelling, imports, await."],
  [/(.+) is not defined/, (m) => "No variable " + m[1] + " in scope: typo, scope or missing import."],
  [/Cannot access '(.+)' before initialization/, (m) => "Move the declaration of " + m[1] + " above its first use (TDZ)."],
  [/is not iterable/, () => "Spread / for-of / destructuring needs an array, string, Map or Set."],
  [/Assignment to constant variable/, () => "Use let, or mutate instead of reassigning."],
  [/Maximum call stack/, () => "Infinite recursion: add a base case."],
  [/JSON/, () => "Invalid JSON: log the raw text, check for HTML or empty body."],
];
function decode(error) {
  for (const [re, fn] of hints) {
    const m = error.message.match(re);
    if (m) return error.name + " -> " + fn(m);
  }
  return error.name + " -> no hint";
}
